CREATE FUNCTION pg_temp.master_fail_audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.action='customer_created' AND NEW.new_values->>'code'='FAIL147' THEN RAISE EXCEPTION 'synthetic master audit failure';END IF;RETURN NEW;END$$;
CREATE TRIGGER synthetic_master_audit_failure BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.master_fail_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.mutate_my_accounting_master('customers','create','{"code":"FAIL147","name_ar":"Audit rollback"}',NULL,NULL,'14700000-0000-4000-8000-000000000123')$$,'P0001','synthetic master audit failure','failed audit aborts entire party mutation');
RESET ROLE;
